 public static function key(string$s):string{return'inventory_invoice_files_'.substr(hash('sha256',$s),0,24);}
 public static function messages(string$locale):array{$en=explode('-',$locale,2)[0]==='en';$out=[];foreach(self::ENGLISH as$s=>$v)$out[self::key($s)]=$en?$v:$s;return$out;}
 public static function text(string$s,array$messages,array$values=[]):string{if(!isset($messages[self::key($s)]))return InventoryLifecycleMessages::text($s,$messages,$values);$replace=[];foreach($values as$k=>$v)$replace['{'.$k.'}']=(string)$v;return strtr($messages[self::key($s)],$replace);}
